const participantData = $('Participant Found?1').first().json;
const firstMatch = participantData.data?.matches?.[0];

if (!firstMatch) {
  throw new Error('No se encontró ningún participante en data.matches');
}

const {
  participantId: pptId,
  planId,
  planName: companyName,
  companyStatus,
  companyStatusDetail,
} = firstMatch;

return {
  json: {
    pptId,
    planId,
    companyName,
    companyStatus,
    companyStatusDetail,
  },
};

